/* t-splash: Underthread opening, B 穿针 (motion by the artist role, work/t-splash/final/b-needle.html; this file is that prototype minus the fake board / controls / URL params).
   Plays when the inline guard in index.html set <html data-splash="1"> (once per session, rt.splash.mode != "off", tab visible, no #nosplash / #push=),
   or on UTSplash.play({ force: true }) (Settings › 开屏动画 › 预览). The board loads underneath and never waits for it.
   Tap / any key skips (that one key is swallowed); reduced motion = fade in 300 ms, hold 0.7 s, fade out 340 ms. Ends with remove() + document "ut-splash-done".
   Brand asset (wordmark mask): not part of the open-source copy. */
(() => {
"use strict";
const R = document.documentElement;
const WM = "data:image/png;base64,";
const END = "stack";   // "row" = horizontal lockup (code kept, not used)
const FADE = 340;
const NS = "http://www.w3.org/2000/svg";
let live = null;

const SVG = `<div class="ut-glow"></div>
<svg id="ut-stage" viewBox="90 200 844 840" xmlns="${NS}" aria-hidden="true">
  <defs>
    <mask id="ut-wmMask" maskUnits="userSpaceOnUse" x="-5000" y="-5000" width="10000" height="10000" style="mask-type:alpha">
      <image id="ut-wmImg" href="${WM}" x="162" y="921" width="700" height="92" preserveAspectRatio="none"/>
    </mask>
    <clipPath id="ut-wmWipe"><rect id="ut-wmWipeR" x="-5000" y="-5000" width="10000" height="10000"/></clipPath>
    <linearGradient id="ut-needleG" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="var(--ut-needle-hi)"/><stop offset=".38" stop-color="var(--ut-needle)"/><stop offset="1" stop-color="var(--ut-needle-lo)"/>
    </linearGradient>
  </defs>
  <g id="ut-lockup">
    <g id="ut-mark">
      <path class="thr" id="ut-t1" d="M212 300 L212 480 C212 659.8 338 790 512 790 C686 790 812 659.8 812 480 L812 260" style="stroke:var(--ut-t1)"/>
      <circle id="ut-k1" cx="812" cy="260" r="38" style="fill:var(--ut-t1)"/>
      <path class="thr" id="ut-t2" d="M296 345 L296 480 C296 611.1 386.7 706 512 706 C637.3 706 728 611.1 728 480 L728 310" style="stroke:var(--ut-t2)"/>
      <circle id="ut-k2" cx="728" cy="310" r="34" style="fill:var(--ut-t2)"/>
      <path class="thr" id="ut-t3" d="M380 390 L380 480 C380 562.4 435.4 622 512 622 C588.6 622 644 562.4 644 480 L644 360" style="stroke:var(--ut-t3)"/>
      <circle id="ut-k3" cx="644" cy="360" r="32" style="fill:var(--ut-t3)"/>
      <g id="ut-barG">
        <g id="ut-stitches"></g>
        <line id="ut-bar" x1="140" y1="480" x2="884" y2="480" stroke="var(--ut-bar)" stroke-width="60" stroke-linecap="round"/>
      </g>
    </g>
    <g id="ut-wm" clip-path="url(#ut-wmWipe)"></g>
    <g id="ut-needle" opacity="0">
      <path d="M0 0 C-30 -8 -150 -23 -214 -23 C-226 -23 -236 -12 -236 0 C-236 12 -226 23 -214 23 C-150 23 -30 8 0 0 Z" fill="none" stroke="var(--ut-bg)" stroke-width="12" stroke-linejoin="round" opacity=".7"/>
      <path d="M0 0 C-30 -8 -150 -23 -214 -23 C-226 -23 -236 -12 -236 0 C-236 12 -226 23 -214 23 C-150 23 -30 8 0 0 Z" fill="url(#ut-needleG)"/>
      <path d="M-34 -5 C-80 -12 -150 -17 -196 -16" fill="none" stroke="var(--ut-needle-hi)" stroke-width="3.5" stroke-linecap="round" opacity=".55"/>
      <rect x="-222" y="-6.5" width="50" height="13" rx="6.5" fill="var(--ut-needle-eye)"/>
    </g>
  </g>
</svg>`;

/* ---------- easing ---------- */
function bez(x1, y1, x2, y2) {
  const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx, cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
  const X = (u) => ((ax * u + bx) * u + cx) * u, Y = (u) => ((ay * u + by) * u + cy) * u;
  return (t) => { if (t <= 0) return 0; if (t >= 1) return 1; let lo = 0, hi = 1, u = t;
    for (let i = 0; i < 24; i++) { const x = X(u); if (Math.abs(x - t) < 1e-5) break; if (x < t) lo = u; else hi = u; u = (lo + hi) / 2; } return Y(u); };
}
const E = {
  brand: bez(.22, .8, .24, 1), io: bez(.65, 0, .35, 1), in: bez(.55, 0, .8, .2),
  outCubic: (t) => 1 - Math.pow(1 - t, 3),
  back: (t, s = 1.7) => { t = t - 1; return 1 + (s + 1) * t * t * t + s * t * t; },
  pass: bez(.42, 0, .32, 1), turn: bez(.45, .1, .4, 1), sew: bez(.32, .12, .84, .7), yank: bez(.6, 0, 1, .5),
};
const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const seg = (t, a, b) => clamp((t - a) / (b - a));
const lerp = (a, b, p) => a + (b - a) * p;
const spring = (dt, amp, hz = 3.2, decay = 120) => dt <= 0 ? 0 : amp * Math.exp(-dt / decay) * Math.sin(dt / 1000 * hz * 2 * Math.PI);

function play(o = {}) {
  if (live) return false;
  const reduce = o.reduce ?? matchMedia("(prefers-reduced-motion: reduce)").matches;
  const th = R.dataset.theme === "white" ? "white" : R.dataset.theme === "light" ? "light" : "dark";
  const splash = document.createElement("div");
  splash.id = "ut-splash"; splash.dataset.th = th; splash.className = "end-" + END;
  splash.setAttribute("role", "img"); splash.setAttribute("aria-label", "Underthread");
  splash.innerHTML = SVG;
  document.body.appendChild(splash);
  R.removeAttribute("data-splash");   // the guard layer goes; the overlay now covers the board

  const $ = (s) => splash.querySelector(s);
  const mk = (tag, attrs, parent) => { const e = document.createElementNS(NS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); parent && parent.appendChild(e); return e; };

  /* ---------- geometry ---------- */
  const T = ["#ut-t1", "#ut-t2", "#ut-t3"].map($), K = ["#ut-k1", "#ut-k2", "#ut-k3"].map($);
  const KC = K.map((k) => [+k.getAttribute("cx"), +k.getAttribute("cy")]);
  const L = T.map((p) => p.getTotalLength());
  const BAR = $("#ut-bar"), BARG = $("#ut-barG"), MARK = $("#ut-mark"), NEEDLE = $("#ut-needle"), STAGE = $("#ut-stage"), STITCHES = $("#ut-stitches");

  /* the bar as 10 stitches; pulled tight they make the whole 140-884 bar */
  const NST = 10, PER = 744 / NST, ST = [];
  for (let i = 0; i < NST; i++) { const c = 140 + PER / 2 + PER * i; ST.push({ c, el: mk("line", { y1: 480, y2: 480, stroke: "var(--ut-bar)", "stroke-linecap": "round" }, STITCHES) }); }

  /* needle track: down into the entry -> outer U -> up out of the knot -> loop onto the bar's right end -> running stitch leftwards -> pulled out */
  const TRACK = [], BOUND = [];
  let acc = 0, last = null;
  const push = (x, y) => { if (last) acc += Math.hypot(x - last[0], y - last[1]); TRACK.push([x, y, acc]); last = [x, y]; };
  for (let y = 300 - 280; y < 300; y += 4) push(212, y); BOUND.push(acc);
  for (let s = 0; s <= L[0]; s += 3) { const p = T[0].getPointAtLength(s); push(p.x, p.y); } BOUND.push(acc);
  for (let y = 256; y >= 190; y -= 4) push(812, y); BOUND.push(acc);
  const cub = (a, b, c, d, u) => (1 - u) ** 3 * a + 3 * (1 - u) ** 2 * u * b + 3 * (1 - u) * u * u * c + u ** 3 * d;
  for (let u = 0; u <= 1; u += .01) push(cub(812, 812, 1040, 940, u), cub(190, 40, 470, 480, u)); BOUND.push(acc);
  for (let x = 940; x >= 108; x -= 3) push(x, 480 - 15 * Math.sin((940 - x) / PER * 2 * Math.PI)); BOUND.push(acc);
  for (let k = 1; k <= 40; k++) push(108 - k * 5, 480 - k * .7); BOUND.push(acc);
  function trackAt(p) {
    p = clamp(p, 0, acc); let lo = 0, hi = TRACK.length - 1;
    while (hi - lo > 1) { const m = (lo + hi) >> 1; if (TRACK[m][2] < p) lo = m; else hi = m; }
    const a = TRACK[lo], b = TRACK[hi], f = (p - a[2]) / Math.max(1e-6, b[2] - a[2]);
    return [lerp(a[0], b[0], f), lerp(a[1], b[1], f)];
  }
  function needlePose(p) { const [x, y] = trackAt(p), [bx, by] = trackAt(p - 60); return { x, y, a: Math.atan2(y - by, x - bx) * 180 / Math.PI }; }

  /* ---------- timeline (ms) ---------- */
  const TL = { in0: 40, pass1: 900, turn1: 1080, sew1: 1430, yank1: 1560, tight0: 1440, wm0: END === "row" ? 1660 : 1560, cam0: 1580, cam1: 2040 };
  const SETTLE = END === "row" ? 2160 : 2000, TOTAL = SETTLE + FADE;
  function needleP(t) {
    if (t < TL.pass1) return lerp(0, BOUND[2], E.pass(seg(t, TL.in0, TL.pass1)));
    if (t < TL.turn1) return lerp(BOUND[2], BOUND[3], E.turn(seg(t, TL.pass1, TL.turn1)));
    if (t < TL.sew1) return lerp(BOUND[3], BOUND[4], E.sew(seg(t, TL.turn1, TL.sew1)));
    return lerp(BOUND[4], BOUND[5], E.yank(seg(t, TL.sew1, TL.yank1)));
  }
  const EYE = 180;
  const strandF = (t) => clamp((needleP(t) - BOUND[0] - EYE) / L[0]);
  const VMAX = (() => { let m = 0; for (let t = 0; t < TL.pass1 + 300; t += 4) m = Math.max(m, strandF(t + 4) - strandF(t)); return m; })();
  const vel = (t) => clamp((strandF(t + 4) - strandF(t)) / VMAX);
  const LAG = [[0, 0], [.012, .045], [.024, .09]];
  const strand = (i, t) => clamp(strandF(t) - (LAG[i][0] + LAG[i][1] * vel(t)) * (1 - strandF(t) ** 6));
  const KNOT_T = [0, 1, 2].map((i) => { for (let t = 0; t < 2000; t += 2) if (strand(i, t) >= 1) return t; return 1100; });
  const STITCH_T = ST.map((s) => { for (let t = TL.turn1; t < TL.yank1; t += 2) { const [x] = trackAt(needleP(t)); if (x < s.c - 12) return t; } return TL.sew1; });

  /* ---------- wordmark ---------- */
  const EDGES = [0, 130, 243, 363, 479, 552, 633, 746, 819, 929, 1048, 1172];
  const WMG = END === "row" ? { x: 1102, y: 327.5, w: 3092, h: 406.3 } : { x: 162, y: 921, w: 700, h: 92 };
  const img = $("#ut-wmImg"); ["x", "y", "w", "h"].forEach((k) => img.setAttribute({ w: "width", h: "height" }[k] || k, WMG[k]));
  const WS = WMG.w / 1172, LET = [];
  for (let j = 0; j < 11; j++) {
    const x0 = WMG.x + EDGES[j] * WS, x1 = WMG.x + EDGES[j + 1] * WS;
    const cp = mk("clipPath", { id: "ut-lc" + j }, $("defs")); mk("rect", { x: x0, width: x1 - x0, y: WMG.y - WMG.h, height: WMG.h * 3 }, cp);
    const g = mk("g", {}, $("#ut-wm")), inner = mk("g", { "clip-path": `url(#ut-lc${j})` }, g);
    const r = mk("rect", { x: WMG.x - 10, y: WMG.y - 10, width: WMG.w + 20, height: WMG.h + 20, mask: "url(#ut-wmMask)" }, inner); r.style.fill = "var(--ut-wm)";
    LET.push({ g, cx: (x0 + x1) / 2 });
  }
  if (END === "row") { const w = $("#ut-wmWipeR"); w.setAttribute("x", 1000); w.setAttribute("width", 9000); }
  const VB_A = [512 - 704, 516.5 - 320, 1408, 640], VB_B = [-10, 516.5 - 977, 4300, 1954], VB_S = [90, 200, 844, 840];

  /* ---------- drawing ---------- */
  function range(el, len, a, b) { a = clamp(a, 0, len); b = clamp(b, 0, len); const d = b - a;
    if (d < .5) { el.style.opacity = 0; return; } el.style.opacity = 1; el.style.strokeDasharray = `${d} ${len + 20}`; el.style.strokeDashoffset = -a; }
  function scaleAt(el, cx, cy, s) { el.setAttribute("transform", `translate(${cx} ${cy}) scale(${Math.max(s, 1e-4)}) translate(${-cx} ${-cy})`); }
  function knot(i, s, op) { scaleAt(K[i], KC[i][0], KC[i][1], s); K[i].style.opacity = s <= .001 ? 0 : op; }
  function letter(j, dx, op) { LET[j].g.setAttribute("transform", `translate(${dx} 0)`); LET[j].g.style.opacity = op; }
  function stitch(i, half, w, dy, op) { const s = ST[i]; s.el.setAttribute("x1", s.c - half); s.el.setAttribute("x2", s.c + half);
    s.el.setAttribute("y1", 480 + dy); s.el.setAttribute("y2", 480 + dy); s.el.setAttribute("stroke-width", w); s.el.style.opacity = op; }
  function setVB(v) { STAGE.setAttribute("viewBox", v.map((n) => n.toFixed(2)).join(" ")); }

  function scene(t) {
    const p = needleP(t), n = needlePose(p);
    NEEDLE.setAttribute("opacity", Math.min(E.outCubic(seg(t, 0, 180)), 1 - E.in(seg(t, TL.sew1 + 30, TL.yank1))));
    const drop = -36 * (1 - E.outCubic(seg(t, 0, 260)));
    NEEDLE.setAttribute("transform", `translate(${n.x} ${n.y + drop}) rotate(${n.a})`);
    for (let i = 0; i < 3; i++) {
      range(T[i], L[i], 0, strand(i, t) * L[i]);
      const kp = seg(t, KNOT_T[i] - 10, KNOT_T[i] + 260);
      const s = kp <= 0 ? 0 : kp < .32 ? lerp(1.55, .84, E.outCubic(kp / .32)) : lerp(.84, 1, E.back((kp - .32) / .68, 2.2));
      knot(i, s, clamp(kp * 5));
    }
    const dir = (t - TL.tight0);
    let allTight = true;
    for (let i = 0; i < NST; i++) {
      const a = seg(t, STITCH_T[i], STITCH_T[i] + 170);
      const tp = E.back(seg(t, TL.tight0 + 16 * i, TL.tight0 + 16 * i + 250), 1.25);
      if (tp < 1 || t < TL.tight0 + 16 * i + 250) allTight = false;
      const half = lerp(lerp(0, 11, E.back(a, 2.6)), PER / 2, tp);
      const w = lerp(lerp(18, 30, E.outCubic(a)), 60, tp);
      const dy = (i % 2 ? 9 : -9) * (1 - E.outCubic(a)) * (1 - tp);
      stitch(i, half, w, dy, a <= 0 ? 0 : clamp(a * 4));
    }
    BAR.style.opacity = allTight ? 1 : 0;
    STITCHES.style.opacity = allTight ? 0 : 1;
    BARG.setAttribute("transform", `translate(${spring(dir - 20, -12, 3.6, 95)} 0)`);
    MARK.setAttribute("transform", `translate(0 ${spring(t - TL.tight0 - 120, 5, 3.2, 110)})`);
    if (END === "row") {
      const c = E.io(seg(t, TL.cam0, TL.cam1));
      setVB(VB_A.map((v, k) => lerp(v, VB_B[k], c)));
      for (let j = 0; j < 11; j++) { const q = E.brand(seg(t, TL.wm0 + j * 12, TL.wm0 + j * 12 + 360)); letter(j, -260 * (1 - q), q); }
    } else {
      setVB(VB_S);
      for (let j = 0; j < 11; j++) { const q = E.brand(seg(t, TL.wm0 + j * 20, TL.wm0 + j * 20 + 420)); letter(j, -18 * (1 - q), q); }
    }
  }
  const finalState = () => scene(SETTLE);

  /* ---------- engine ---------- */
  const glow = $(".ut-glow");
  const RM_TOTAL = 1000 + FADE, DUR = reduce ? RM_TOTAL : TOTAL;
  function render(t) {
    if (reduce) { finalState(); const a = E.outCubic(seg(t, 0, 300)); STAGE.style.opacity = a; glow.style.opacity = a; splash.style.opacity = 1 - seg(t, 1000, RM_TOTAL); return; }
    scene(Math.min(t, SETTLE)); glow.style.opacity = E.outCubic(seg(t, 0, 600));
    const f = seg(t, SETTLE, TOTAL); splash.style.opacity = 1 - E.in(f); STAGE.style.transform = `scale(${1 + .03 * E.io(f)})`;
  }
  let start = null, skipping = null, done = false;
  const onKey = (e) => { if (done) return; e.preventDefault(); e.stopImmediatePropagation(); skip(); };   // the skipping key never reaches the board
  function finish() {
    if (done) return; done = true; clearTimeout(guard);
    removeEventListener("keydown", onKey, true); splash.remove(); live = null;
    document.dispatchEvent(new CustomEvent("ut-splash-done"));
  }
  function tick(now) {
    if (done) return;
    if (start === null) start = now;
    if (skipping !== null) {
      const f = clamp((now - skipping) / 240); finalState(); glow.style.opacity = 1; STAGE.style.opacity = 1; splash.style.opacity = 1 - E.io(f);
      if (f >= 1) return finish(); requestAnimationFrame(tick); return;
    }
    const t = now - start; render(t);
    if (t >= DUR) return finish(); requestAnimationFrame(tick);
  }
  function skip() { if (done || skipping !== null) return; skipping = performance.now(); }
  splash.addEventListener("pointerdown", (e) => { e.preventDefault(); skip(); });
  addEventListener("keydown", onKey, true);
  const guard = setTimeout(finish, DUR + 1500);   // rAF can stall (background tab): never leave the overlay behind
  render(0); requestAnimationFrame(tick);
  live = { skip };
  return true;
}

window.UTSplash = { play, skip: () => live && live.skip(), get playing() { return !!live; } };
if (R.dataset.splash === "1") play();
})();
